Repair the complete source below. Export the same API in the corrected complete source file. `resolvePanel` validates that feature ids are unique and that every id and message key is non-empty, throwing `TypeError` otherwise. Empty features return `null`. A matching selected id chooses that feature; an absent or unknown selected id chooses the first feature. Message keys are replaced from `messages`, falling back to the key itself when missing. The returned object is fresh, feature order is otherwise irrelevant, and neither input is mutated.

```typescript
export interface PanelFeature {
  readonly id: string;
  readonly titleKey: string;
  readonly detailKey: string;
  readonly altKey: string;
}

export interface ResolvedPanel {
  readonly id: string;
  readonly title: string;
  readonly detail: string;
  readonly imageAlt: string;
}

export function resolvePanel(
  features: readonly PanelFeature[],
  selectedId: string | undefined,
  messages: Readonly<Record<string, string>>,
): ResolvedPanel | null {
  const ids = new Set<string>();
  for (const feature of features) {
    if ([feature.id, feature.titleKey, feature.detailKey, feature.altKey].some((value) => value.length === 0) || ids.has(feature.id)) {
      throw new TypeError("Invalid feature collection");
    }
    ids.add(feature.id);
  }
  if (features.length === 0) return null;
  const index = selectedId === undefined
    ? 0
    : features.findIndex((feature) => feature.id === selectedId);
  const feature = features[index];
  const translate = (key: string): string => messages[key] ?? key;
  return {
    id: feature.id,
    title: translate(feature.titleKey),
    detail: translate(feature.detailKey),
    imageAlt: translate(feature.altKey),
  };
}
```

