import { resolvePanel } from './solution';
import type { PanelFeature, ResolvedPanel } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsTypeError(action: () => unknown, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  if (!(error instanceof TypeError)) throw new Error(message);
}

equal(resolvePanel([], undefined, {}), null, 'empty features return null');

const features: PanelFeature[] = [
  { id: 'first', titleKey: 'first.title', detailKey: 'first.detail', altKey: 'first.alt' },
  { id: 'second', titleKey: 'second.title', detailKey: 'second.detail', altKey: 'second.alt' },
];
const messages: Record<string, string> = {
  'first.title': 'First title',
  'first.detail': 'First detail',
  'second.title': 'Second title',
  'second.alt': 'Second alt',
};
const selected = resolvePanel(features, 'second', messages);
if (selected === null) throw new Error('selected feature unexpectedly null');
equal(selected.id, 'second', 'matching id selected');
equal(selected.title, 'Second title', 'title translated');
equal(selected.detail, 'second.detail', 'missing message falls back to key');
equal(selected.imageAlt, 'Second alt', 'alt translated');

const absent = resolvePanel(features, undefined, messages);
if (absent === null) throw new Error('default panel unexpectedly null');
equal(absent.id, 'first', 'absent selected id chooses first feature');
const unknown = resolvePanel(features, 'not-present', messages);
if (unknown === null) throw new Error('unknown selection unexpectedly null');
equal(unknown.id, 'first', 'unknown selected id chooses first feature');

assert(absent !== unknown, 'each result must be fresh');
assert(absent !== (features[0] as unknown as ResolvedPanel), 'result must not alias feature');
(selected as { title: string }).title = 'mutated result';
equal(messages['second.title'], 'Second title', 'mutating result does not mutate messages');
equal(features[1].titleKey, 'second.title', 'feature input remains unchanged');

throwsTypeError(
  () => resolvePanel([
    { id: 'same', titleKey: 'a', detailKey: 'b', altKey: 'c' },
    { id: 'same', titleKey: 'd', detailKey: 'e', altKey: 'f' },
  ], undefined, {}),
  'duplicate ids rejected',
);
throwsTypeError(
  () => resolvePanel([{ id: '', titleKey: 'a', detailKey: 'b', altKey: 'c' }], undefined, {}),
  'empty id rejected',
);
throwsTypeError(
  () => resolvePanel([{ id: 'id', titleKey: '', detailKey: 'b', altKey: 'c' }], undefined, {}),
  'empty title key rejected',
);
throwsTypeError(
  () => resolvePanel([{ id: 'id', titleKey: 'a', detailKey: '', altKey: 'c' }], undefined, {}),
  'empty detail key rejected',
);
throwsTypeError(
  () => resolvePanel([{ id: 'id', titleKey: 'a', detailKey: 'b', altKey: '' }], undefined, {}),
  'empty alt key rejected',
);

